INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20CPB1S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $JKL$, point $M$ lies on side $KL$ such that $JM$ bisects $\\angle J$. If $\\angle K = 43°$ and $\\angle L = 71°$, what is the measure, in degrees, of $\\angle JML$?', NULL, $lyceon_json$[{"key":"A","text":"$76°$"},{"key":"B","text":"$104°$"},{"key":"C","text":"$66°$"},{"key":"D","text":"$110°$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, $\\angle J = 180° - 43° - 71° = 66°$. Since $JM$ bisects $\\angle J$, the angle $\\angle MJL = \\frac{66°}{2} = 33°$. In triangle $JML$, the angles sum to $180°$: $\\angle MJL + \\angle L + \\angle JML = 180°$, so $33° + 71° + \\angle JML = 180°$, giving $\\angle JML = 76°$. The value $104°$ results from finding the supplementary angle $180° - 76°$, which is $\\angle JMK$ rather than the requested $\\angle JML$. The value $66°$ comes from using the full angle $J$ instead of the bisected half. The value $110°$ arises from an incorrect equation setup using $\\angle K$ in place of $\\angle L$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21T1MCK', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'In the $xy$-plane, the point $(a, 11)$ lies in the solution region of the system of inequalities below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2298068', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $7x - 23 = 26$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$49$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. Add $23$ to both sides of $7x - 23 = 26$ to get $7x = 49$, then divide both sides by $7$ to get $x = 7$. The distractor $49$ results from stopping after isolating $7x$ without dividing by the coefficient. The distractor $3$ comes from computing $26 - 23 = 3$ without accounting for the coefficient of $x$. The distractor $-7$ results from a sign error when dividing $49$ by $7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23IDIUF', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $h$ is defined by $h(x) = ax + b$, where $a$ and $b$ are constants. If $h(3) = 22$ and $h(11) = 54$, what is the value of $h(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Find the slope $a$ using the two given values: $a = \\frac{h(11) - h(3)}{11 - 3} = \\frac{54 - 22}{8} = \\frac{32}{8} = 4$. Substitute into $h(3) = 22$: $4(3) + b = 22$, so $12 + b = 22$, giving $b = 10$. Since $h(x) = 4x + 10$, we have $h(0) = 4(0) + 10 = 10$. A common error is computing the slope incorrectly by inverting the fraction to get $\\frac{8}{32} = \\frac{1}{4}$, which yields $b = 22 - \\frac{3}{4} = \\frac{85}{4}$. Another error is finding $a = 4$ correctly but then computing $b = 22 - 3 = 19$ by forgetting to multiply $a$ by $3$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM248VKEY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has a slant height of $25$ cm and a base radius of $7$ cm. The cone is cut by a plane parallel to the base at a height equal to $\\frac{3}{4}$ of the cone''s total height from the base. What is the volume of the smaller cone formed above the cut?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{49\\pi}{8}$"},{"key":"B","text":"$98\\pi$"},{"key":"C","text":"$\\frac{147\\pi}{8}$"},{"key":"D","text":"$\\frac{49\\pi}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, find the cone''s height using the slant height and radius: $h = \\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$ cm. The cut is at $\\frac{3}{4}$ of the height from the base, so the smaller cone above the cut has height $24 - 18 = 6$ cm. By similar triangles, the scale factor is $\\frac{6}{24} = \\frac{1}{4}$, so the smaller cone''s radius is $7 \\times \\frac{1}{4} = \\frac{7}{4}$ cm. Its volume is $\\frac{1}{3}\\pi\\left(\\frac{7}{4}\\right)^2(6) = \\frac{1}{3}\\pi \\cdot \\frac{49}{16} \\cdot 6 = \\frac{294\\pi}{48} = \\frac{49\\pi}{8}$ cubic centimeters. The value $98\\pi$ results from using the full base radius $7$ instead of the scaled radius $\\frac{7}{4}$ for the small cone. The value $\\frac{147\\pi}{8}$ comes from using the cut height of $18$ cm instead of the small cone''s actual height of $6$ cm. The value $\\frac{49\\pi}{6}$ arises from an arithmetic error in simplifying the fraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
