INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25KLZR4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In the $xy$-plane, a line passes through the origin and makes an angle of $\\theta$ with the positive $x$-axis, where $\\cos(\\theta) = \\frac{3}{7}$. The line intersects the circle $x^2 + y^2 = 343$ at point $P$ in the first quadrant. What is the $y$-coordinate of point $P$?', NULL, $lyceon_json$[{"key":"A","text":"$3\\sqrt{7}$"},{"key":"B","text":"$7\\sqrt{10}$"},{"key":"C","text":"$2\\sqrt{70}$"},{"key":"D","text":"$\\frac{2\\sqrt{10}}{7}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $P$ lies on $x^2 + y^2 = 343$, the distance from the origin to $P$ is $r = \\sqrt{343} = 7\\sqrt{7}$. The $y$-coordinate is $r\\sin(\\theta)$. From $\\cos(\\theta) = \\frac{3}{7}$, we get $\\sin(\\theta) = \\sqrt{1 - \\frac{9}{49}} = \\sqrt{\\frac{40}{49}} = \\frac{2\\sqrt{10}}{7}$. Therefore $y = 7\\sqrt{7} \\cdot \\frac{2\\sqrt{10}}{7} = 2\\sqrt{70}$. The value $3\\sqrt{7}$ is the $x$-coordinate ($7\\sqrt{7} \\cdot \\frac{3}{7} = 3\\sqrt{7}$), not the $y$-coordinate. The value $7\\sqrt{10}$ arises from omitting the factor of $2$ in $\\sin(\\theta)$. The value $\\frac{2\\sqrt{10}}{7}$ is $\\sin(\\theta)$ itself, without multiplying by the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26K68PA', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 5)}{4} = 9$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{2}$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$17$"},{"key":"D","text":"$-\\frac{17}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{17}{2}$. Multiply both sides by $4$ to get $3(2x - 5) = 36$. Divide both sides by $3$ to get $2x - 5 = 12$. Add $5$ to both sides: $2x = 17$. Divide by $2$: $x = \\frac{17}{2}$. The distractor $\\frac{7}{2}$ arises from subtracting $5$ instead of adding $5$ when isolating $2x$, yielding $2x = 7$. The distractor $17$ comes from finding $2x = 17$ but not dividing by $2$. The distractor $-\\frac{17}{2}$ is a sign error applied to the correct value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26U06PV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ employees found that $68$ commute by car only, $47$ commute by train only, $31$ commute by both car and train, and the rest use other methods. If an employee who commutes by car (with or without train) is selected at random, what is the probability that this employee also commutes by train?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{200}$"},{"key":"B","text":"$\\frac{31}{99}$"},{"key":"C","text":"$\\frac{31}{78}$"},{"key":"D","text":"$\\frac{99}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of employees who commute by car (with or without train) is $68 + 31 = 99$. Among these, $31$ also commute by train. The conditional probability is $\\frac{31}{99}$. The result $\\frac{31}{200}$ divides by the total number of employees rather than restricting to car commuters, ignoring the conditional aspect. The result $\\frac{31}{78}$ uses $47 + 31 = 78$ (train commuters) as the denominator instead of car commuters. The result $\\frac{99}{200}$ gives the probability of commuting by car overall, not the conditional probability of also using train.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM271QWAF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 2^{x-3} + 5$. Which of the following correctly describes the graph of $f$?', NULL, $lyceon_json$[{"key":"A","text":"The graph has a horizontal asymptote at $y = 5$ and passes through $(3, 6)$."},{"key":"B","text":"The graph has a horizontal asymptote at $y = 3$ and passes through $(5, 9)$."},{"key":"C","text":"The graph has a horizontal asymptote at $y = 5$ and passes through $(3, 7)$."},{"key":"D","text":"The graph has a vertical asymptote at $x = 3$ and passes through $(4, 7)$."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that the graph has a horizontal asymptote at $y = 5$ and passes through $(3, 6)$. As $x \\to -\\infty$, $2^{x-3} \\to 0$, so $f(x) \\to 5$, giving a horizontal asymptote at $y = 5$. At $x = 3$: $f(3) = 2^{3-3} + 5 = 2^0 + 5 = 1 + 5 = 6$. The distractor claiming a horizontal asymptote at $y = 3$ confuses the horizontal shift parameter with the vertical shift; the $-3$ in the exponent shifts the graph right, not up. The distractor stating the graph passes through $(3, 7)$ results from computing $2^0 = 2$ instead of the correct value $2^0 = 1$. The distractor with a vertical asymptote at $x = 3$ misidentifies the type of asymptote; exponential functions have horizontal asymptotes, not vertical ones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27EGNCH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the $xy$-plane has center $(2, -5)$ and passes through the point $(14, 0)$. A chord of this circle has its midpoint at $(7, -5)$. What is the length of the chord?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24', ARRAY['24'], E'The radius is the distance from the center $(2, -5)$ to the point $(14, 0)$: $r = \\sqrt{(14 - 2)^2 + (0 - (-5))^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13$. The distance from the center $(2, -5)$ to the chord''s midpoint $(7, -5)$ is $d = \\sqrt{(7 - 2)^2 + (-5 - (-5))^2} = 5$. A radius drawn to the midpoint of a chord is perpendicular to the chord, creating a right triangle with the radius as hypotenuse, $d$ as one leg, and half the chord as the other leg. Half the chord length is $\\sqrt{r^2 - d^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. Therefore the full chord length is $2 \\times 12 = 24$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28MX8XT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The mean score of $5$ students on a quiz is $67$. When a sixth student''s score is included, the mean score changes to $71$. What is the sixth student''s score?', NULL, $lyceon_json$[{"key":"A","text":"$47$"},{"key":"B","text":"$71$"},{"key":"C","text":"$87$"},{"key":"D","text":"$91$"}]$lyceon_json$::jsonb, 'D', NULL, E'The total score for $5$ students is $5 \\times 67 = 335$. The total score for $6$ students is $6 \\times 71 = 426$. The sixth student''s score is $426 - 335 = 91$. The distractor $47$ comes from reversing the subtraction: $6 \\times 67 - 5 \\times 71 = 402 - 355 = 47$, swapping which count goes with which mean. The distractor $71$ arises from assuming the sixth student scored exactly the new mean. The distractor $87$ results from computing $(71 - 67) \\times 5 + 67 = 87$, incorrectly multiplying the change in mean by $5$ instead of $6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2909C68', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x - 2y = 19$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{19}{2}$"},{"key":"B","text":"$\\frac{19}{2}$"},{"key":"C","text":"$\\frac{19}{5}$"},{"key":"D","text":"$-\\frac{5}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-\\frac{19}{2}$. To find the $y$-intercept, set $x = 0$: $5(0) - 2y = 19$, so $-2y = 19$, giving $y = -\\frac{19}{2}$. The distractor $\\frac{19}{2}$ results from dropping the negative sign when dividing by $-2$. The distractor $\\frac{19}{5}$ comes from setting $y = 0$ and solving for $x$, which gives the $x$-intercept instead. The distractor $-\\frac{5}{2}$ confuses the $y$-intercept with the slope of the line.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29T2555', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A retailer marks up a product by $40\\%$ over its cost and then offers a $25\\%$ discount on the marked-up price during a sale. If the sale price of the product is $\\$63$, what was the original cost, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the original cost be $C$. After a $40\\%$ markup, the marked-up price is $1.40C$. After a $25\\%$ discount on the marked-up price, the sale price is $0.75 \\times 1.40C = 1.05C$. Setting $1.05C = 63$ gives $C = \\frac{63}{1.05} = 60$ dollars.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ADMHZV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The following data set shows the number of books read by $9$ students during the summer: $$2, 4, 5, 7, 8, 9, 11, 13, 16$$ What is the median number of books read?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$8.33$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has $9$ values listed in order. The median is the $\\frac{9+1}{2} = 5$th value, which is $8$. The distractor $7$ results from selecting the $4$th value instead of the $5$th. The distractor $8.33$ comes from computing the mean ($\\frac{75}{9} \\approx 8.33$) instead of the median. The distractor $9$ results from selecting the $6$th value instead of the $5$th.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CZA2BC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The graph of the function $f(x) = a(x - 4)^2 + 7$ passes through the point $(1, -11)$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'Substitute the point $(1, -11)$ into $f(x) = a(x - 4)^2 + 7$: $-11 = a(1 - 4)^2 + 7$. Simplify: $-11 = a(9) + 7$, so $9a = -18$, giving $a = -2$. This means the parabola opens downward with vertex $(4, 7)$ and passes through $(1, -11)$, which is $18$ units below the vertex, consistent with $a = -2$ and a horizontal distance of $3$ from the vertex.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D51OO3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher recorded quiz scores and their frequencies as shown below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E37Q58', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 11x - 37$. What is the value of $f(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$-29$"},{"key":"C","text":"$103$"},{"key":"D","text":"$66$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $29$. Substitute $x = 6$: $f(6) = 11(6) - 37 = 66 - 37 = 29$. The distractor $-29$ results from a sign error, negating the correct result. The distractor $103$ comes from adding $37$ instead of subtracting: $66 + 37 = 103$. The distractor $66$ results from computing $11 \\times 6$ but not subtracting $37$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E8G7V0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $ABC$ with the right angle at $C$, $\\sin(A) = \\frac{15}{113}$. If $BC = 15$, what is the length of $AC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '112', ARRAY['112'], E'In right triangle $ABC$ with the right angle at $C$, $\\sin(A) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{BC}{AB} = \\frac{15}{113}$. This gives $AB = 113$. Using the Pythagorean theorem, $AC = \\sqrt{AB^2 - BC^2} = \\sqrt{113^2 - 15^2} = \\sqrt{12769 - 225} = \\sqrt{12544} = 112$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F7OMX0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher wants to determine whether a new study method improves exam scores. She recruits $80$ volunteers and lets each student choose whether to use the new method or their usual method. Students using the new method score $11$ points higher on average. Which of the following is a valid concern about this study design?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $80$ is too small to detect any difference."},{"key":"B","text":"Because students self-selected into groups, differences in motivation or ability may confound the results."},{"key":"C","text":"The study should have used a larger margin of error."},{"key":"D","text":"The $11$-point difference proves the new method is effective, so there is no concern."}]$lyceon_json$::jsonb, 'B', NULL, E'Allowing students to choose their own group creates a self-selection bias. Students who opt for the new method may be more motivated or academically stronger, making it impossible to attribute the $11$-point difference solely to the study method. A sample size of $80$ is not inherently too small; whether it provides sufficient power depends on effect size and variability, not on an arbitrary threshold. The margin of error is a property of the estimate, not something the researcher adjusts as a design choice. Declaring the difference proves effectiveness ignores the confounding introduced by self-selection.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G1L5UR', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $g$ satisfies $g(2) = 17$ and $g(5) = 38$. What is the rate of change of $g$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$21$"},{"key":"D","text":"$\\frac{1}{7}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. The rate of change of a linear function is the slope: $\\frac{g(5) - g(2)}{5 - 2} = \\frac{38 - 17}{3} = \\frac{21}{3} = 7$. The distractor $21$ results from computing only the difference in outputs ($38 - 17 = 21$) without dividing by the change in the input. The distractor $3$ comes from computing only the change in inputs ($5 - 2 = 3$) and confusing it with the rate of change. The distractor $\\frac{1}{7}$ comes from inverting the slope, dividing the change in inputs by the change in outputs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HAA2AC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the sum of the solutions to the equation $x^2 - 13x + 42 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The equation $x^2 - 13x + 42 = 0$ factors as $(x - 6)(x - 7) = 0$, so the solutions are $x = 6$ and $x = 7$. Their sum is $6 + 7 = 13$. Alternatively, by Vieta''s formulas, the sum of the roots of $x^2 + bx + c = 0$ equals $-b$, so the sum is $-(-13) = 13$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I62FSG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces $87$ parts in $3$ hours at a constant rate. How many parts will the factory produce in $11$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$261$"},{"key":"B","text":"$290$"},{"key":"C","text":"$319$"},{"key":"D","text":"$957$"}]$lyceon_json$::jsonb, 'C', NULL, E'The production rate is $\\frac{87}{3} = 29$ parts per hour. Over $11$ hours, the factory produces $29 \\times 11 = 319$ parts. The distractor $261$ comes from computing $29 \\times 9 = 261$, as if only the additional $11 - 3 + 1 = 9$ hours were counted. The distractor $290$ results from rounding or miscalculating $29 \\times 10 = 290$. The distractor $957$ arises from multiplying $87 \\times 11 = 957$ without dividing by the original $3$-hour base.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JASZNC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'In a certain paint mixture, the ratio of blue paint to white paint is $3$ to $11$. If a painter uses $33$ ounces of white paint, how many ounces of blue paint are needed?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$9$"},{"key":"C","text":"$11$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of blue to white paint is $3:11$. Since $33$ ounces of white paint is used, and $33 \\div 11 = 3$, the scale factor is $3$. Multiplying the blue ratio value by the same factor gives $3 \\times 3 = 9$ ounces. The distractor $3$ results from using the ratio value directly without scaling. The distractor $11$ comes from dividing $33 \\div 3 = 11$, incorrectly applying the blue-paint ratio number as a divisor. The distractor $22$ arises from subtracting $33 - 11 = 22$ instead of setting up a proportion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JE126M', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the angles measure $47°$ and $68°$. What is the measure, in degrees, of the third angle?', NULL, $lyceon_json$[{"key":"A","text":"$55°$"},{"key":"B","text":"$65°$"},{"key":"C","text":"$75°$"},{"key":"D","text":"$115°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the angles in any triangle is $180°$. The third angle is $180° - 47° - 68° = 65°$. The value $115°$ results from adding $47°$ and $68°$ instead of subtracting them from $180°$. The values $55°$ and $75°$ arise from arithmetic errors in the subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JNJY7J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$"},{"key":"B","text":"$169\\pi$"},{"key":"C","text":"$26\\pi$"},{"key":"D","text":"$52\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(13) = 26\\pi$. The value $13\\pi$ comes from using $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The value $169\\pi$ is the area ($\\pi r^2 = \\pi(13)^2$), not the circumference. The value $52\\pi$ results from using $4\\pi r$ instead of $2\\pi r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K04WJK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $3(2x^2 - 5x) + 4(x^2 + 3x)$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^2 - 3x$"},{"key":"B","text":"$10x^2 + 27x$"},{"key":"C","text":"$6x^2 - 3x$"},{"key":"D","text":"$10x^2 - 27x$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $10x^2 - 3x$. Distribute the $3$ to get $6x^2 - 15x$ and the $4$ to get $4x^2 + 12x$. Combining like terms: $6x^2 + 4x^2 = 10x^2$ and $-15x + 12x = -3x$. The distractor $10x^2 + 27x$ results from treating $-5x$ as $+5x$ before distributing, yielding $15x + 12x = 27x$. The distractor $6x^2 - 3x$ comes from only distributing the $3$ and ignoring the $4x^2$ term. The distractor $10x^2 - 27x$ arises from treating $+3x$ as $-3x$, giving $-15x - 12x = -27x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L33ZB8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'At a veterinary clinic, $\\frac{5}{13}$ of the animals are cats and the rest are dogs. Of the cats, $\\frac{1}{3}$ have been vaccinated, and of the dogs, $\\frac{3}{8}$ have been vaccinated. If a vaccinated animal is selected at random from the clinic, what is the probability that it is a dog? (Assume no other animal types.)', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{8}$"},{"key":"B","text":"$\\frac{9}{14}$"},{"key":"C","text":"$\\frac{3}{13}$"},{"key":"D","text":"$\\frac{5}{14}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the total number of animals be $312$ (a common multiple of $13$, $3$, and $8$). Then there are $\\frac{5}{13} \\times 312 = 120$ cats and $192$ dogs. Vaccinated cats: $\\frac{1}{3} \\times 120 = 40$. Vaccinated dogs: $\\frac{3}{8} \\times 192 = 72$. Total vaccinated: $40 + 72 = 112$. The probability that a vaccinated animal is a dog is $\\frac{72}{112} = \\frac{9}{14}$. The result $\\frac{3}{8}$ is just the vaccination rate among dogs, not the conditional probability given that the animal is vaccinated. The result $\\frac{3}{13}$ comes from dividing vaccinated dogs by the total number of animals ($\\frac{72}{312} = \\frac{3}{13}$), which ignores the condition that the selected animal is vaccinated. The result $\\frac{5}{14}$ equals $\\frac{40}{112}$, the probability that a vaccinated animal is a cat, answering for the wrong species.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LL6GJ3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $5$ cm and a height of $18$ cm. A cone has the same radius and the same height as the cylinder. What is the positive difference between the volume of the cylinder and the volume of the cone? (Express your answer as a coefficient of $\\pi$, so that if the answer were $50\\pi$, you would enter $50$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '300', ARRAY['300'], E'The volume of the cylinder is $V_{\\text{cyl}} = \\pi r^2 h = \\pi(5)^2(18) = 450\\pi$ cubic centimeters. The volume of the cone is $V_{\\text{cone}} = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(5)^2(18) = 150\\pi$ cubic centimeters. The difference is $450\\pi - 150\\pi = 300\\pi$, so the coefficient of $\\pi$ is $300$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LNEI00', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was $12{,}400$ in 2018 and $14{,}508$ in 2023. What is the percent increase in population from 2018 to 2023?', NULL, $lyceon_json$[{"key":"A","text":"$14.5\\%$"},{"key":"B","text":"$17\\%$"},{"key":"C","text":"$21\\%$"},{"key":"D","text":"$117\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase in population is $14{,}508 - 12{,}400 = 2{,}108$. The percent increase is $\\frac{2{,}108}{12{,}400} \\times 100 = 17\\%$. The distractor $14.5\\%$ comes from dividing the increase by the final population instead of the initial population: $\\frac{2{,}108}{14{,}508} \\approx 14.5\\%$. The distractor $21\\%$ results from dividing $2{,}108$ by $10{,}000$ instead of $12{,}400$, giving $21.08\\%$ rounded to $21\\%$. The distractor $117\\%$ comes from computing $\\frac{14{,}508}{12{,}400} \\times 100 = 117\\%$ without subtracting $100\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LS7HH4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $7x - 4y = 20$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $3$. Rewrite line $p$ in slope-intercept form: $7x - 4y = 20$ becomes $y = \\frac{7}{4}x - 5$, so the slope of line $p$ is $\\frac{7}{4}$. The slope of a perpendicular line is the negative reciprocal: $-\\frac{4}{7}$. Using point-slope form with $(7, -1)$: $y - (-1) = -\\frac{4}{7}(x - 7)$, which gives $y + 1 = -\\frac{4}{7}x + 4$, so $y = -\\frac{4}{7}x + 3$. The $y$-intercept is $3$. The distractor $-5$ is the $y$-intercept of line $p$, not line $q$, reflecting a conceptual gap about which line was asked for. The distractor $5$ results from incorrectly handling the sign of the point $y$-coordinate, writing $y - 1$ instead of $y + 1$. The distractor $-3$ comes from an arithmetic error when combining constants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OMURQE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collected data on the relationship between hours of weekly exercise and resting heart rate for $30$ adults. The line of best fit is $y = -1.9x + 83$, where $x$ is hours of exercise per week and $y$ is resting heart rate in beats per minute. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of weekly exercise, the predicted resting heart rate decreases by $1.9$ beats per minute."},{"key":"B","text":"For each additional beat per minute of resting heart rate, the predicted weekly exercise decreases by $1.9$ hours."},{"key":"C","text":"For each additional hour of weekly exercise, the predicted resting heart rate increases by $1.9$ beats per minute."},{"key":"D","text":"A person who exercises $0$ hours per week has a predicted resting heart rate of $83$ beats per minute."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $-1.9$ means that for each one-unit increase in $x$ (one additional hour of weekly exercise), the predicted value of $y$ (resting heart rate) decreases by $1.9$ beats per minute. The distractor stating that weekly exercise decreases by $1.9$ hours per beat reverses the roles of the independent and dependent variables. The distractor claiming a $1.9$-beat increase ignores the negative sign of the slope. The distractor describing a resting heart rate of $83$ beats per minute at $0$ hours of exercise interprets the $y$-intercept, not the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PG59AB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, the exterior angle at vertex $F$ measures $131°$. If $\\angle D = 54°$, what is the measure, in degrees, of $\\angle E$?', NULL, $lyceon_json$[{"key":"A","text":"$49°$"},{"key":"B","text":"$77°$"},{"key":"C","text":"$95°$"},{"key":"D","text":"$126°$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $131° = \\angle D + \\angle E = 54° + \\angle E$, which gives $\\angle E = 131° - 54° = 77°$. The value $49°$ comes from finding the interior angle at $F$ ($180° - 131° = 49°$) but stopping there without finding $\\angle E$. The value $126°$ results from computing $180° - 54°$, which is the supplement of $\\angle D$ rather than the requested angle. The value $95°$ reflects an arithmetic error in the subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R106YX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 18x + 4y + 21 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{21}$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$64$"}]$lyceon_json$::jsonb, 'C', NULL, E'Completing the square: $(x^2 - 18x + 81) + (y^2 + 4y + 4) = -21 + 81 + 4$, which gives $(x - 9)^2 + (y + 2)^2 = 64$. This is standard form with $r^2 = 64$, so $r = 8$. The value $64$ is $r^2$, not $r$ — a common error of stopping before taking the square root. The value $\\sqrt{21}$ results from taking the square root of the constant term $21$ from the original equation without completing the square. The value $4$ arises from an arithmetic error in completing the square.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RLCWF5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'In the equation $\\frac{2x + 9}{5} - \\frac{x - 3}{2} = 7$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-37', ARRAY['-37'], E'Multiply every term by the least common denominator $10$ to eliminate fractions: $10 \\cdot \\frac{2x + 9}{5} - 10 \\cdot \\frac{x - 3}{2} = 10 \\cdot 7$, which gives $2(2x + 9) - 5(x - 3) = 70$. Distribute: $4x + 18 - 5x + 15 = 70$. Combine like terms: $-x + 33 = 70$. Subtract $33$ from both sides: $-x = 37$. Multiply by $-1$: $x = -37$. A common error is distributing the negative sign incorrectly in $-5(x - 3)$, writing $-5x - 15$ instead of $-5x + 15$, which would lead to $-x + 3 = 70$ and $x = -67$. Another error is using $10$ as the LCD but multiplying only some terms, producing an incorrect intermediate equation.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RW0B4Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A scatterplot shows the relationship between the number of months since a sapling was planted, $x$, and the sapling''s height in centimeters, $y$. The line of best fit is $y = 2.7x + 15.4$. The actual measured height at $x = 14$ months is $57$ centimeters. What is the residual for this data point?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3.8', ARRAY['19/5', '3.8'], E'The predicted height at $x = 14$ is $y = 2.7(14) + 15.4 = 37.8 + 15.4 = 53.2$ centimeters. The residual is the actual value minus the predicted value: $57 - 53.2 = 3.8$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S3Y1Q7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a $30°$-$60°$-$90°$ triangle, the hypotenuse has length $22$. What is the length of the side opposite the $30°$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$11\\sqrt{3}$"},{"key":"B","text":"$11$"},{"key":"C","text":"$22\\sqrt{3}$"},{"key":"D","text":"$\\frac{22}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle is half the hypotenuse. Therefore the length is $\\frac{22}{2} = 11$. The value $11\\sqrt{3}$ is the length of the side opposite the $60°$ angle, not the $30°$ angle. The value $22\\sqrt{3}$ results from multiplying the hypotenuse by $\\sqrt{3}$ instead of dividing by $2$. The value $\\frac{22}{3}$ comes from dividing by $3$ instead of $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S94X93', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from the same large population. Sample A has $n = 400$ and finds a sample proportion of $\\hat{p}_A = 0.52$. Sample B has $n = 1{,}600$ and finds $\\hat{p}_B = 0.47$. Both use $95\\%$ confidence intervals. Which of the following statements must be true?', NULL, $lyceon_json$[{"key":"A","text":"The confidence interval from Sample B is approximately half the width of the confidence interval from Sample A."},{"key":"B","text":"The confidence intervals from both samples must overlap because they are drawn from the same population."},{"key":"C","text":"The confidence interval from Sample A is more likely to contain the true population proportion than the confidence interval from Sample B."},{"key":"D","text":"The true population proportion is more likely to be closer to $0.47$ than to $0.52$."}]$lyceon_json$::jsonb, 'A', NULL, E'The width of a confidence interval for a proportion is proportional to $\\frac{1}{\\sqrt{n}}$. Since $\\frac{\\sqrt{400}}{\\sqrt{1600}} = \\frac{20}{40} = \\frac{1}{2}$, Sample B''s interval is approximately half the width of Sample A''s interval (assuming similar proportions, which gives similar standard errors in the numerator). The claim that the intervals must overlap is not guaranteed; with finite samples, two $95\\%$ confidence intervals from the same population can fail to overlap due to sampling variability. Both intervals have the same $95\\%$ confidence level, so neither is more likely to contain the true proportion than the other. While the larger sample provides a more precise estimate, one cannot conclude from these two samples alone that the true proportion is closer to $0.47$; each sample estimate is subject to random variation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T55WYD', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $5x + 8 > 33$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtracting $8$ from both sides of $5x + 8 > 33$ gives $5x > 25$, and dividing both sides by $5$ gives $x > 5$. The only value greater than $5$ among the choices is $6$. The value $5$ does not satisfy the strict inequality since $5(5) + 8 = 33$, which equals but is not greater than $33$. The values $3$ and $4$ are both less than $5$ and produce results less than $33$ when substituted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTQEKU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $17$ cm and a width of $9$ cm. What is the area of the rectangle, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$52$"},{"key":"B","text":"$144$"},{"key":"C","text":"$26$"},{"key":"D","text":"$153$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $17 \\times 9 = 153$ square centimeters. The value $52$ is the perimeter ($2(17 + 9) = 52$), not the area. The value $144$ comes from an arithmetic slip such as computing $16 \\times 9$ instead of $17 \\times 9$. The value $26$ is simply the sum $17 + 9$, which gives neither the area nor the perimeter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W20ECM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $250$ households in a county and finds that $38\\%$ of them have solar panels, with a margin of error of $6$ percentage points at a $95\\%$ confidence level. The researcher wants to reduce the margin of error to $3$ percentage points. Which of the following changes would best achieve this?', NULL, $lyceon_json$[{"key":"A","text":"Survey $500$ households instead of $250$"},{"key":"B","text":"Increase the sample size to approximately $1{,}000$ households"},{"key":"C","text":"Reduce the confidence level to $90\\%$"},{"key":"D","text":"Exclude households that do not have solar panels from the sample"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely proportional to the square root of the sample size. To halve the margin of error from $6$ to $3$ percentage points, the sample size must be multiplied by $4$: approximately $250 \\times 4 = 1{,}000$ households. Doubling the sample to $500$ would only reduce the margin of error by a factor of $\\sqrt{2} \\approx 1.41$, yielding roughly $\\frac{6}{1.41} \\approx 4.3$ percentage points, not $3$. Reducing the confidence level would decrease the margin of error, but it changes the confidence guarantee rather than improving precision at the same confidence level, and does not target $3$ points specifically. Excluding non-solar households would introduce bias and invalidate the estimate entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WC1VZU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore offers an $18\\%$ discount on a textbook originally priced at $\\$45$. What is the sale price of the textbook, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$8.10$"},{"key":"B","text":"$\\$36.00$"},{"key":"C","text":"$\\$36.90$"},{"key":"D","text":"$\\$53.10$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount amount is $0.18 \\times 45 = 8.10$ dollars. The sale price is $45 - 8.10 = 36.90$ dollars. The distractor $\\$8.10$ is the discount amount itself, not the sale price. The distractor $\\$36.00$ comes from computing $18\\%$ of $\\$45$ as $\\$9.00$ (treating $18\\%$ as $\\frac{18}{90}$ or rounding), giving $45 - 9 = 36$. The distractor $\\$53.10$ results from adding the discount instead of subtracting: $45 + 8.10 = 53.10$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WFZ452', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(2x + 7)^2 - (2x - 7)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$8x^2$"},{"key":"C","text":"$56x$"},{"key":"D","text":"$98$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $56x$. Expanding $(2x + 7)^2 = 4x^2 + 28x + 49$ and $(2x - 7)^2 = 4x^2 - 28x + 49$. Subtracting: $(4x^2 + 28x + 49) - (4x^2 - 28x + 49) = 56x$. Alternatively, using the difference-of-squares identity $a^2 - b^2 = (a+b)(a-b)$ with $a = 2x+7$ and $b = 2x-7$ gives $(4x)(14) = 56x$. The distractor $0$ reflects the misconception that $(a+b)^2 - (a-b)^2 = 0$. The distractor $8x^2$ comes from only subtracting the $x^2$ terms: $4x^2 - (-4x^2) = 8x^2$, ignoring the cross terms. The distractor $98$ results from only subtracting the constant terms: $49 - (-49) = 98$, misapplying the subtraction to the constants alone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WUPXP3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $150$ residents of a city found that the mean commute time is $37$ minutes with a margin of error of $4$ minutes. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"All residents of the city commute between $33$ and $41$ minutes."},{"key":"B","text":"The sample mean is likely between $33$ and $41$ minutes."},{"key":"C","text":"It is plausible that the true mean commute time for all residents is between $33$ and $41$ minutes."},{"key":"D","text":"Exactly $95\\%$ of residents commute between $33$ and $41$ minutes."}]$lyceon_json$::jsonb, 'C', NULL, E'A sample mean of $37$ minutes with a margin of error of $4$ minutes produces a confidence interval of $33$ to $41$ minutes. This interval estimates where the true population mean plausibly lies. The claim that all residents commute within this range confuses a population mean estimate with individual values. The claim that the sample mean is between $33$ and $41$ is incorrect because the sample mean is already known to be exactly $37$; the interval estimates the population mean. The claim that exactly $95\\%$ of residents fall in this range confuses a confidence interval for the mean with a prediction interval for individual values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
