INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XAIMIV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company conducts a randomized controlled trial with $600$ participants to test a new allergy medication. Participants are randomly assigned to receive either the medication or a placebo. After $8$ weeks, the medication group reports $29\\%$ fewer allergy symptoms on average than the placebo group ($p = 0.03$). A critic argues that the result is not meaningful because the study did not use a $p$-value threshold of $0.01$. Which of the following best evaluates the critic''s argument?', NULL, $lyceon_json$[{"key":"A","text":"The critic is correct; a $p$-value of $0.03$ provides no evidence against the null hypothesis."},{"key":"B","text":"The critic is incorrect; the randomized design ensures the result is free from all bias, making the $p$-value irrelevant."},{"key":"C","text":"The critic applies an arbitrary threshold; $p = 0.03$ indicates the observed difference is unlikely under the null hypothesis, and the study's randomized design supports a causal interpretation."},{"key":"D","text":"The critic is correct because the $29\\%$ reduction could be entirely due to the placebo effect."}]$lyceon_json$::jsonb, 'C', NULL, E'A $p$-value of $0.03$ means there is only a $3\\%$ probability of observing a difference this large or larger under the null hypothesis, which provides meaningful evidence against it. The critic''s insistence on $p < 0.01$ imposes an arbitrary threshold; while lower $p$-values provide stronger evidence, $0.03$ is below the widely used $0.05$ level and still indicates statistical significance. The claim that $p = 0.03$ provides no evidence overstates the threshold requirement. The claim that randomization makes the $p$-value irrelevant is wrong because randomization controls for confounding but does not eliminate the need for statistical testing. The claim that the reduction is entirely due to placebo effect is contradicted by the study design, which includes a placebo control group specifically to account for that effect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XECQ8B', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line in the $xy$-plane passes through the points $(3, 11)$ and $(7, 23)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'First find the slope: $m = \\frac{23 - 11}{7 - 3} = \\frac{12}{4} = 3$. Using the point $(3, 11)$ in the slope-intercept form $y = mx + b$: $11 = 3(3) + b$, so $11 = 9 + b$, giving $b = 2$. The $y$-intercept is $2$. A common error is inverting the slope calculation as $\\frac{7 - 3}{23 - 11} = \\frac{1}{3}$, which would yield a different intercept. Another error is computing $23 - 11 = 12$ and stopping there without dividing by the change in $x$.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XJTEN7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = x^2 - 6x + 13$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$13$"},{"key":"C","text":"$-6$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $4$. Completing the square: $f(x) = x^2 - 6x + 13 = (x - 3)^2 + 4$. Since $(x - 3)^2 \\geq 0$ for all real $x$, the minimum value of $f(x)$ is $0 + 4 = 4$, occurring at $x = 3$. The distractor $13$ is the $y$-intercept $f(0)$, not the minimum. The distractor $-6$ is the coefficient of $x$, confused with the minimum value. The distractor $3$ is the $x$-coordinate of the vertex, not the minimum value of the function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YJG5EG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A map uses a scale of $\\frac{3}{8}$ inch to represent $5$ miles. Two towns are $11.25$ inches apart on the map. A delivery truck travels between the two towns at an average speed of $50$ miles per hour. How many hours will the trip take?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'First, determine how many miles one inch represents. Since $\\frac{3}{8}$ inch corresponds to $5$ miles, one inch corresponds to $5 \\div \\frac{3}{8} = 5 \\times \\frac{8}{3} = \\frac{40}{3}$ miles. The actual distance is $11.25 \\times \\frac{40}{3} = \\frac{11.25 \\times 40}{3} = \\frac{450}{3} = 150$ miles. At $50$ miles per hour, the trip takes $\\frac{150}{50} = 3$ hours.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YPGIN5', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter charges a flat fee of $\\$47$ plus $\\$19$ per hour for a job. The carpenter wants to earn more than $\\$236$ on a particular job. Which inequality represents all possible numbers of hours $h$ the carpenter must work?', NULL, $lyceon_json$[{"key":"A","text":"$h > \\frac{189}{19}$"},{"key":"B","text":"$h \\geq 10$"},{"key":"C","text":"$h > \\frac{236}{19}$"},{"key":"D","text":"$h > \\frac{283}{19}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The carpenter''s total earnings are $47 + 19h$, and this must exceed $236$: $47 + 19h > 236$. Subtracting $47$ from both sides gives $19h > 189$, so $h > \\frac{189}{19}$. The choice $h \\geq 10$ incorrectly converts the strict inequality to a non-strict one and rounds $\\frac{189}{19} \\approx 9.947$ up to $10$. The choice $h > \\frac{236}{19}$ results from dividing $236$ by $19$ without first subtracting the flat fee. The choice $h > \\frac{283}{19}$ comes from adding $47$ to $236$ instead of subtracting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YS5NJ3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that people who drink herbal tea at least three times per week have lower blood pressure on average than those who do not drink herbal tea. The report is based on survey responses from $1{,}200$ adults. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking herbal tea causes lower blood pressure."},{"key":"B","text":"There is an association between drinking herbal tea and lower blood pressure."},{"key":"C","text":"Lower blood pressure causes people to prefer herbal tea."},{"key":"D","text":"The survey proves that herbal tea is an effective treatment for high blood pressure."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study is based on survey responses (an observational study), it can identify an association between herbal tea consumption and lower blood pressure but cannot establish causation. The claim that herbal tea causes lower blood pressure goes beyond what an observational study can support, since confounding variables (such as overall health habits) may explain the difference. The claim that lower blood pressure causes tea preference reverses the direction of the observed relationship without evidence. Stating the survey proves herbal tea is an effective treatment overstates the finding, since observational data cannot prove treatment efficacy.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YUSHO8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq -7$ and $x \\neq 7$, which expression is equivalent to $\\frac{x^2 + 11x + 28}{x^2 - 49}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 4}{x - 7}$"},{"key":"B","text":"$\\frac{x + 4}{x + 7}$"},{"key":"C","text":"$\\frac{x - 4}{x - 7}$"},{"key":"D","text":"$\\frac{11x + 28}{-49}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{x + 4}{x - 7}$. Factor the numerator: $x^2 + 11x + 28 = (x + 4)(x + 7)$. Factor the denominator using the difference of squares: $x^2 - 49 = (x + 7)(x - 7)$. Canceling the common factor $(x + 7)$ yields $\\frac{x + 4}{x - 7}$. The distractor $\\frac{x + 4}{x + 7}$ results from canceling $(x - 7)$ instead of $(x + 7)$, reflecting confusion about which factor is shared. The distractor $\\frac{x - 4}{x - 7}$ arises from a sign error when factoring the numerator, writing $(x - 4)(x + 7)$ instead of $(x + 4)(x + 7)$. The distractor $\\frac{11x + 28}{-49}$ comes from incorrectly canceling $x^2$ from numerator and denominator as though they were separate terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z0FBT9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $5$ purple beads, $8$ yellow beads, and $3$ white beads. If one bead is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{16}$"},{"key":"B","text":"$\\frac{1}{2}$"},{"key":"C","text":"$\\frac{8}{13}$"},{"key":"D","text":"$\\frac{5}{16}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of beads is $5 + 8 + 3 = 16$. The probability of selecting a yellow bead is $\\frac{8}{16} = \\frac{1}{2}$. The result $\\frac{3}{16}$ corresponds to finding the probability of selecting a white bead rather than a yellow one. The result $\\frac{8}{13}$ comes from excluding the white beads from the total count, using only $5 + 8 = 13$. The result $\\frac{5}{16}$ comes from finding the probability of selecting a purple bead instead.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z20MW2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a data set is given by $y = 4.5x + 12$, where $x$ represents the number of hours studied and $y$ represents the predicted quiz score. What is the predicted quiz score for a student who studied $8$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$44$"},{"key":"C","text":"$48$"},{"key":"D","text":"$96$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 8$ into the equation gives $y = 4.5(8) + 12 = 36 + 12 = 48$. The distractor $36$ results from computing $4.5 \\times 8 = 36$ but omitting the $y$-intercept of $12$. The distractor $44$ comes from using a slope of $4$ instead of $4.5$, giving $4 \\times 8 + 12 = 44$. The distractor $96$ arises from multiplying by the $y$-intercept instead: $12 \\times 8 = 96$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z25WPP', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A store sells two types of gift baskets. A small basket contains $3$ candles and $5$ soaps and costs $\\$33$. A large basket contains $7$ candles and $4$ soaps and costs $\\$54$. What is the cost, in dollars, of one candle?', NULL, $lyceon_json$[{"key":"A","text":"$\\$3$"},{"key":"B","text":"$\\$4$"},{"key":"C","text":"$\\$5$"},{"key":"D","text":"$\\$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Let $c$ represent the cost of one candle and $s$ the cost of one soap. The system is $3c + 5s = 33$ and $7c + 4s = 54$. To eliminate $s$, multiply the first equation by $4$ and the second by $5$: $12c + 20s = 132$ and $35c + 20s = 270$. Subtracting the first from the second gives $23c = 138$, so $c = 6$. Substituting back gives $3(6) + 5s = 33$, so $5s = 15$ and $s = 3$. The cost of one candle is $\\$6$. The value $\\$3$ is the cost of one soap, not a candle. The value $\\$4$ might result from an error in the elimination step. The value $\\$5$ comes from an arithmetic mistake such as computing $138 \\div 23$ incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJC8IW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $x + y = 12$ and $xy = 35$, what is the value of $x^2 + y^2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '74', ARRAY['74'], E'Using the algebraic identity $x^2 + y^2 = (x + y)^2 - 2xy$, substitute the given values: $x^2 + y^2 = 12^2 - 2(35) = 144 - 70 = 74$. To verify, the values of $x$ and $y$ satisfy $t^2 - 12t + 35 = 0$, which factors as $(t - 5)(t - 7) = 0$, giving $x = 5, y = 7$ (or vice versa). Indeed, $5^2 + 7^2 = 25 + 49 = 74$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZZD559', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What are the solutions to the equation $3x^2 + 7x - 20 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -\\frac{5}{3}$ and $x = 4$"},{"key":"B","text":"$x = \\frac{5}{3}$ and $x = -4$"},{"key":"C","text":"$x = 5$ and $x = -4$"},{"key":"D","text":"$x = -5$ and $x = \\frac{4}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $x = \\frac{5}{3}$ and $x = -4$. Using the quadratic formula with $a = 3$, $b = 7$, and $c = -20$: the discriminant is $b^2 - 4ac = 49 + 240 = 289 = 17^2$. Then $x = \\frac{-7 \\pm 17}{6}$, giving $x = \\frac{10}{6} = \\frac{5}{3}$ or $x = \\frac{-24}{6} = -4$. The distractor $x = -\\frac{5}{3}$ and $x = 4$ reverses both signs. The distractor $x = 5$ and $x = -4$ results from not dividing $10$ by $6$, taking only the numerator. The distractor $x = -5$ and $x = \\frac{4}{3}$ comes from misapplying the formula with incorrect arithmetic in the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22KLNLL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes an inference based on the passage?', E'After decades of importing nearly all its vanilla, Madagascar began cultivating the crop domestically in the early twentieth century. The island''s northeastern Sava region proved uniquely suited to vanilla orchids, which require a narrow temperature range, high humidity, and partial shade. By the 1960s, Madagascar supplied roughly 70 percent of the world''s natural vanilla. However, because vanilla flowers must be hand-pollinated within a 12-hour window after blooming, production costs remain high, and synthetic vanillin — derived from wood pulp or petroleum — now accounts for over 97 percent of vanilla flavoring used globally.', $lyceon_json$[{"key":"A","text":"The labor-intensive nature of vanilla cultivation contributes to the widespread adoption of synthetic alternatives."},{"key":"B","text":"Madagascar has recently stopped growing vanilla in favor of more profitable crops."},{"key":"C","text":"Synthetic vanillin is chemically identical to the compound found in natural vanilla pods."},{"key":"D","text":"Most consumers prefer the taste of synthetic vanillin to that of natural vanilla extract."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage links high production costs — driven by the labor-intensive requirement for hand-pollination — to the dominance of synthetic vanillin, which accounts for over 97 percent of vanilla flavoring globally. The inference that labor-intensive cultivation contributes to the adoption of synthetic alternatives follows directly from this connection. The claim that Madagascar has stopped growing vanilla contradicts the passage, which describes ongoing production without mentioning cessation. The claim about chemical identity introduces a scientific comparison not addressed in the passage. The claim about consumer taste preference introduces a subjective judgment the passage neither states nor implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23985IN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The marine biologist Petra Vasquez has spent over fourteen years studying bioluminescent organisms in deep-ocean trenches. Her research has revealed that certain species of lanternfish produce light patterns unique to their geographic ______ Vasquez believes these patterns may function as a form of territorial signaling.', $lyceon_json$[{"key":"A","text":"region,"},{"key":"B","text":"region; however,"},{"key":"C","text":"region."},{"key":"D","text":"region; for example,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses a period to separate two independent clauses: one about lanternfish producing light patterns unique to their geographic region, and one about Vasquez''s belief regarding territorial signaling. Using a comma alone creates a comma splice, which violates sentence boundary conventions. Using ''however'' after a semicolon incorrectly signals a contrast between the two clauses, but the second clause extends the observation by proposing a function for the patterns rather than contradicting their existence. Using ''for example'' after a semicolon incorrectly signals that the second clause illustrates the first, but Vasquez''s hypothesis about territorial signaling is a separate claim, not an instance of light patterns being geographically unique.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23E8SVB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying deep-ocean hydrothermal vents have documented an ecosystem that flourishes in conditions once thought incompatible with life. The organisms thriving near these vents ______ the widely held assumption that sunlight is a prerequisite for complex biological communities.', $lyceon_json$[{"key":"A","text":"undermine"},{"key":"B","text":"perpetuate"},{"key":"C","text":"fabricate"},{"key":"D","text":"chronicle"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "undermine." The passage describes organisms that flourish without sunlight, which challenges or weakens the assumption that sunlight is necessary. "Undermine" means to weaken or damage the foundation of something, fitting this context precisely. "Perpetuate" means to continue or maintain, which is the opposite of what these organisms do to the assumption. "Fabricate" means to invent or manufacture something false, which does not describe the organisms'' relationship to the assumption. "Chronicle" means to record events in order, which does not convey the idea of challenging or weakening.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23SCZKX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Coral reefs support roughly one-quarter of all marine species despite covering less than one percent of the ocean floor. _______ marine biologists often refer to coral reefs as the "rainforests of the sea."', $lyceon_json$[{"key":"A","text":"For this reason,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "For this reason," because the second sentence presents a consequence of the fact stated in the first: the extraordinary biodiversity of coral reefs leads biologists to compare them to rainforests. "In contrast" incorrectly signals opposition between two ideas that are logically consistent. "For instance" wrongly frames the second sentence as an example rather than a result. "Nevertheless" implies an unexpected outcome, but comparing reefs to rainforests follows naturally from their biodiversity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24QBXWU', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding from the passage, if accurate, most directly supports Ishikawa''s hypothesis?', E'Ecologist Rena Ishikawa hypothesizes that urban green roofs reduce ambient air temperatures in surrounding neighborhoods by increasing evapotranspiration. To test this, her team monitored temperatures at 23 sites across a mid-sized city over three summers. Sites within 200 meters of buildings with green roofs consistently recorded afternoon temperatures 1.7 to 2.4 degrees Celsius lower than comparable sites lacking nearby green roofs. The temperature difference persisted even after the researchers controlled for building height, street width, and tree canopy coverage.', $lyceon_json$[{"key":"A","text":"Sites near green roofs recorded afternoon temperatures 1.7 to 2.4 degrees Celsius lower than sites without nearby green roofs."},{"key":"B","text":"Ishikawa's team monitored temperatures at 23 sites across a mid-sized city."},{"key":"C","text":"The researchers controlled for building height, street width, and tree canopy coverage."},{"key":"D","text":"The study was conducted over three consecutive summers."}]$lyceon_json$::jsonb, 'A', NULL, E'Ishikawa''s hypothesis is that green roofs reduce ambient air temperatures via evapotranspiration. The finding that sites near green roofs were 1.7 to 2.4 degrees Celsius cooler directly supports the predicted temperature reduction. The detail about monitoring 23 sites describes the study''s scope but does not itself demonstrate a temperature effect. The mention of controlling for confounding variables describes methodology, not a result that supports the hypothesis. The detail about three summers indicates the study''s duration, which bears on reliability but does not constitute evidence of a temperature difference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW268AIIA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Historian Elara Okonkwo has challenged the conventional narrative that the 1847 trade agreement between the two nations was negotiated on equal terms. Her archival research reveals that one delegation arrived with detailed intelligence about the other''s fiscal vulnerabilities, giving them leverage that effectively ______ the negotiation before formal talks began.', $lyceon_json$[{"key":"A","text":"predetermined"},{"key":"B","text":"sanctioned"},{"key":"C","text":"inaugurated"},{"key":"D","text":"publicized"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "predetermined." The passage argues that one delegation''s advance intelligence about fiscal vulnerabilities gave them such decisive leverage that the outcome of the negotiation was effectively fixed before it started. "Predetermined" means decided or established in advance, which captures this meaning. "Sanctioned" means officially approved or authorized, but the passage describes covert advantage, not official approval of the process. "Inaugurated" means formally begun or initiated, but the passage states the effect occurred before formal talks began, and the point is about fixing the outcome, not starting the process. "Publicized" means made widely known, which contradicts the passage''s implication that the intelligence was a private strategic advantage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26LLHBS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A team of conservationists at the Thornberry Wildlife Reserve has been tracking the migration routes of sandhill cranes for the past eleven years. The evidence collected by the ______ that the cranes have gradually shifted their stopover sites northward by an average of forty-seven kilometers per decade.', $lyceon_json$[{"key":"A","text":"team shows"},{"key":"B","text":"team show"},{"key":"C","text":"teams shows"},{"key":"D","text":"teams show"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the verb is ''evidence,'' which is an uncountable singular noun requiring the singular verb ''shows.'' The intervening phrase ''collected by the team'' does not change the number of the subject. Since the passage mentions ''a team'' (singular), the noun must remain ''team,'' not ''teams.'' The choice ''team show'' incorrectly pairs the singular subject ''evidence'' with the plural verb ''show.'' The choices using ''teams'' incorrectly pluralize the noun when only one team has been mentioned in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27USDTR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The political theorist Adaeze Obi-Fernandez argues that participatory budgeting initiatives, which allow residents of a municipality to directly allocate a portion of public funds, ______ civic engagement more effectively than traditional town-hall meetings do, provided that organizers ensure equitable access to the deliberation process.', $lyceon_json$[{"key":"A","text":"promotes"},{"key":"B","text":"promote"},{"key":"C","text":"has promoted"},{"key":"D","text":"is promoting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is ''initiatives,'' a plural noun. The intervening nonrestrictive clause (''which allow residents...funds'') separates the subject from its verb, but the verb must still agree with the plural subject. The correct form is ''promote,'' the plural present-tense verb. The choice ''promotes'' uses a singular verb that would agree with ''budgeting'' or ''portion'' but not with the actual subject ''initiatives.'' The choice ''has promoted'' uses a singular auxiliary (''has'') that fails to agree with the plural subject, and the present-perfect tense is inconsistent with the passage''s framing of an ongoing general argument rather than a completed action. The choice ''is promoting'' similarly uses a singular auxiliary and implies a currently unfolding action rather than a general theoretical claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ASM816', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the argument presented in Text 2?', E'Text 1: Literary scholar Priya Nagarajan maintains that the oral storytelling traditions of pre-colonial South Asia cannot be meaningfully analyzed through Western narratological frameworks. She argues that concepts such as "plot arc" and "character development," which emerged from the study of European novels, presuppose a linear temporal structure and an individualist conception of selfhood that are fundamentally at odds with the cyclical, communal nature of South Asian oral performance. Imposing these categories, Nagarajan contends, distorts the very features that make these traditions distinctive.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BRU9V3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'The fruit of the New Zealand kauri tree, Agathis australis, produces a resin so durable that fragments buried in peat bogs have remained chemically intact for tens of thousands of years. Paleoclimatologists prize these ancient resin deposits because the carbon isotopes trapped within them record atmospheric conditions at the time of formation.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BZYCOY', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, the architect Rowan Okafor proposed an unconventional design for the Millhaven civic library: a series of interconnected hexagonal chambers arranged around a central atrium. Many local officials dismissed the concept as ______ the completed building, which opened in 1991, won three national architecture awards and became the city''s most visited public space.', $lyceon_json$[{"key":"A","text":"impractical, however,"},{"key":"B","text":"impractical, consequently,"},{"key":"C","text":"impractical;"},{"key":"D","text":"impractical, moreover,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses a semicolon to properly join two independent clauses. The first clause states that officials dismissed the design as impractical, and the second states that the building won awards and became popular—a clear contrast. The choice using a comma followed by ''however'' creates a comma splice; a conjunctive adverb after a comma cannot join two independent clauses. The choice using ''consequently'' misrepresents the logical relationship: the building''s success was not a consequence of officials dismissing the design. The choice using ''moreover'' incorrectly signals that the second clause adds supporting information to the first, when in fact it contradicts it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DYZDQ5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The playwright Aphra Behn is widely credited as one of the first English women to earn a living through writing. Her comedies were commercially successful in the 1670s and 1680s, rivaling the popularity of works by male contemporaries. _______ after her death in 1689, Behn''s reputation declined sharply, and her plays were rarely performed for nearly two centuries.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"However,"},{"key":"D","text":"Therefore,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "However," because the passage shifts from describing Behn''s commercial success during her lifetime to the contrasting decline of her reputation after death. "Similarly" wrongly implies that the decline mirrors her success. "Specifically" incorrectly suggests the final sentence elaborates on or narrows the preceding claim. "Therefore" implies the decline was a logical consequence of her success, which contradicts the passage''s contrast between the two periods.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FALP14', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The architect Lina Vasquez rejected the prevailing trend of designing buildings with vast glass facades. She argued that such structures, while visually striking, were thermally ______, requiring enormous expenditures of energy to maintain comfortable interior temperatures throughout the year.', $lyceon_json$[{"key":"A","text":"profligate"},{"key":"B","text":"opaque"},{"key":"C","text":"diminutive"},{"key":"D","text":"melodious"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "profligate." The passage describes buildings that waste enormous amounts of energy, and "profligate" means recklessly extravagant or wasteful, which precisely characterizes structures that squander thermal energy. "Opaque" means not transparent, which describes a visual property unrelated to the energy waste the architect criticizes. "Diminutive" means extremely small, which does not logically describe a thermal property of buildings. "Melodious" means having a pleasant tune, a quality entirely unrelated to architecture or energy consumption.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1KR5I', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the passage?', E'In a 2019 study, archaeologist Marta Velandia challenged the prevailing view that the Muisca people of pre-colonial Colombia used gold objects solely for ceremonial purposes. By analyzing trace wear patterns on 137 gold artifacts recovered from domestic middens near Sogamoso, Velandia demonstrated that many items — including thin discs and elongated pins — showed microscopic abrasion consistent with repeated daily handling. She argued that these objects likely served utilitarian functions such as fastening garments and scraping hides, activities that would produce the distinctive wear signatures she observed. Velandia acknowledged, however, that ceremonial and practical uses were not mutually exclusive: some artifacts bore both ritual iconography and utilitarian wear marks.', $lyceon_json$[{"key":"A","text":"Velandia's research suggests that Muisca gold artifacts served practical everyday functions in addition to ceremonial ones."},{"key":"B","text":"Velandia proved that previous scholars had entirely misidentified the purpose of Muisca gold objects."},{"key":"C","text":"The Muisca people valued gold primarily for its economic worth rather than its spiritual significance."},{"key":"D","text":"Wear-pattern analysis is a newly invented technique that has transformed archaeological methodology worldwide."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Velandia''s argument that Muisca gold artifacts had utilitarian functions alongside ceremonial ones, supported by wear-pattern evidence. The choice stating that the artifacts served practical everyday functions in addition to ceremonial ones captures this nuanced finding. The choice claiming Velandia proved previous scholars entirely wrong overstates her position; the passage notes she acknowledged ceremonial and practical uses were not mutually exclusive. The choice about economic worth introduces a concept — economic valuation — not discussed in the passage. The choice describing wear-pattern analysis as newly invented and transformative goes well beyond the passage, which does not characterize the technique''s novelty or global impact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KABF2V', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is contrasting Bo Bardi''s design philosophy with the approach of architects who prioritize individual buildings as standalone aesthetic achievements. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LCW2HI', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the primary purpose of the passage?', E'Philosopher Kwame Gyekye has argued that the communitarian ethics characteristic of Akan societies in Ghana should not be conflated with a denial of individual identity. In Gyekye''s moderate communitarianism, the community indeed shapes moral norms and provides the social context within which personhood develops, but individuals retain the capacity for autonomous moral judgment. This capacity, Gyekye contends, is what allows members of a community to critically evaluate and, when warranted, revise inherited customs. He distinguishes his position from what he calls radical communitarianism, which treats the individual as wholly constituted by communal relationships and thus unable to stand apart from collective norms. For Gyekye, the tension between communal belonging and individual autonomy is not a defect to be resolved but a productive feature of moral life.', $lyceon_json$[{"key":"A","text":"To explain Gyekye's view that communitarian ethics can accommodate individual moral autonomy without abandoning communal values"},{"key":"B","text":"To argue that Akan societies historically prioritized individual rights over communal obligations"},{"key":"C","text":"To contrast two Ghanaian philosophers' opposing theories about the origins of moral norms"},{"key":"D","text":"To demonstrate that radical communitarianism is the dominant ethical framework in contemporary Akan thought"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage outlines Gyekye''s moderate communitarianism, which holds that communal ethics and individual moral autonomy coexist productively. The choice describing Gyekye''s view as accommodating individual moral autonomy without abandoning communal values accurately reflects this central purpose. The choice about Akan societies historically prioritizing individual rights reverses the passage''s emphasis: Gyekye does not claim individual rights take precedence, but rather that autonomy operates within a communal framework. The choice about contrasting two Ghanaian philosophers is unsupported; only Gyekye''s views are presented, and the contrast is between his moderate communitarianism and a position he labels radical communitarianism, not between two named philosophers. The choice claiming radical communitarianism is dominant misrepresents the passage, which presents it as a position Gyekye argues against rather than endorses or identifies as prevailing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MZ7AGV', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if valid, would most directly undermine Fontaine''s proposed mechanism for the observed effect?', E'Neuroscientist Elara Fontaine proposes that chronic sleep deprivation impairs moral reasoning not by reducing general cognitive capacity but by selectively degrading activity in the ventromedial prefrontal cortex (vmPFC), a region associated with integrating emotional signals into decision-making. In a 2023 experiment, Fontaine''s team asked 84 participants to evaluate a series of moral dilemmas after either a full night of sleep or 36 hours of wakefulness. Both groups performed comparably on logic puzzles administered alongside the dilemmas, but sleep-deprived participants were 31 percent more likely to endorse utilitarian solutions that disregarded individual welfare — a pattern Fontaine attributes to diminished vmPFC-mediated emotional input rather than impaired reasoning ability.', $lyceon_json$[{"key":"A","text":"Brain imaging revealed that vmPFC activity in sleep-deprived participants was statistically indistinguishable from that in rested participants during the moral dilemmas."},{"key":"B","text":"Sleep-deprived participants took slightly longer to complete the moral dilemmas than rested participants did."},{"key":"C","text":"A follow-up survey showed that sleep-deprived participants reported feeling less alert than rested participants."},{"key":"D","text":"Rested participants who scored highest on empathy questionnaires were least likely to endorse utilitarian solutions."}]$lyceon_json$::jsonb, 'A', NULL, E'Fontaine''s mechanism specifically attributes the moral-reasoning shift to degraded vmPFC activity. If brain imaging showed that vmPFC activity was statistically indistinguishable between the two groups during moral dilemmas, the proposed mechanism — selective vmPFC degradation — would be directly contradicted. The finding about sleep-deprived participants taking longer could reflect many factors and does not address whether vmPFC activity specifically was impaired. The finding about reduced alertness is expected during sleep deprivation but does not bear on whether the vmPFC-mediated pathway is the mechanism responsible for the moral-reasoning shift. The finding about rested participants'' empathy scores concerns individual differences within the control group rather than the causal mechanism linking sleep deprivation to altered moral judgment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NEMTRT', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the authors of the two texts approach the topic of urban green spaces?', E'Text 1: Urban green spaces offer measurable psychological benefits to city residents. A 2021 longitudinal study tracked over four thousand participants in three European cities and found that individuals living within three hundred meters of a park reported significantly lower levels of perceived stress and scored higher on standardized well-being assessments than those living farther away. The researchers controlled for income, age, and employment status, strengthening the conclusion that proximity to green space itself contributes to mental health outcomes.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OU06HN', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an introduction to an essay about baobab trees for readers who are unfamiliar with the species. Which choice most effectively uses relevant information from the notes to introduce the baobab tree to this audience?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OXBAS3', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes the role of the scene involving Satyananda in Chandrasekaran''s argument?', E'Literary scholar Priya Chandrasekaran argues that the Bengali novelist Bankim Chandra Chattopadhyay used irony in his 1882 novel Anandamath not to endorse militant nationalism, as many twentieth-century readers assumed, but to expose the limitations of revolutionary fervor when divorced from ethical reflection. Chandrasekaran points to a pivotal scene in which the rebel leader Satyananda, upon achieving military victory, finds himself unable to articulate a coherent vision for the society he intends to build. Rather than celebrating this triumph, the narrative lingers on Satyananda''s silence and confusion, which Chandrasekaran reads as Chattopadhyay''s deliberate commentary on the hollowness of victory without moral purpose.', $lyceon_json$[{"key":"A","text":"It serves as evidence that Chattopadhyay used irony to critique revolutionary action lacking ethical grounding."},{"key":"B","text":"It demonstrates that Chattopadhyay admired Satyananda as a model of principled leadership."},{"key":"C","text":"It reveals that Chattopadhyay opposed all forms of political resistance in colonial Bengal."},{"key":"D","text":"It illustrates how twentieth-century readers correctly interpreted Chattopadhyay's nationalist message."}]$lyceon_json$::jsonb, 'A', NULL, E'Chandrasekaran cites Satyananda''s post-victory silence and confusion as evidence that Chattopadhyay employed irony to critique revolutionary action divorced from ethical reflection. The choice identifying the scene as evidence for ironic critique of ungrounded revolution matches this argumentative function. The choice suggesting admiration for Satyananda as a principled leader contradicts the passage, which describes the scene as exposing Satyananda''s inability to articulate a moral vision. The choice claiming Chattopadhyay opposed all political resistance goes beyond the argument; Chandrasekaran''s point concerns revolution without ethical reflection, not opposition to resistance in general. The choice about twentieth-century readers'' correct interpretation reverses the passage''s claim that those readers misread the novel as endorsing militant nationalism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PTO4KC', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research for over a century. Its genome was fully sequenced in the year 2000, and it shares roughly sixty percent of its genes with humans. <u>Because of these genetic similarities, researchers frequently use fruit flies to study human diseases such as Parkinson''s and Alzheimer''s.</u> Recent studies have employed gene-editing tools to create fly models that replicate specific disease mutations observed in patients.', $lyceon_json$[{"key":"A","text":"It explains why a particular organism is useful for studying certain human conditions."},{"key":"B","text":"It presents a counterargument to a claim made earlier in the text."},{"key":"C","text":"It provides biographical information about the scientists involved in the research."},{"key":"D","text":"It questions the reliability of the research methodology described in the text."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the sentence explains why the organism is useful for studying certain human conditions. The underlined sentence explicitly connects the genetic similarities mentioned earlier to the practical application of using fruit flies for disease research. The choice describing a counterargument is incorrect because the underlined sentence builds on the preceding information rather than opposing it. The choice about biographical information is incorrect because no scientists are named or described in the sentence. The choice about questioning methodology is incorrect because the sentence endorses the research approach rather than casting doubt on it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q5AXK9', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the passage, which choice can most reasonably be inferred about the relationship between the Younger Dryas climate shift and Natufian settlements?', E'Paleoclimatologist Yael Amitai has studied oxygen-isotope ratios in stalactites from Soreq Cave in Israel to reconstruct precipitation patterns over the past 25,000 years. Her data reveal that during the Younger Dryas — a cold interval roughly 12,900 to 11,700 years ago — the eastern Mediterranean experienced a sharp decline in rainfall, coinciding with the collapse of several early Natufian settlements in the Levant. Amitai cautions, however, that her isotope record reflects regional moisture availability rather than conditions at any single archaeological site, and that the Natufian settlement pattern involved both abandonments and new foundations during the same period. Some communities relocated to areas near perennial springs, suggesting adaptive responses rather than a uniform societal breakdown.', $lyceon_json$[{"key":"A","text":"Reduced rainfall likely pressured some Natufian communities to relocate, but the response was varied rather than uniformly catastrophic."},{"key":"B","text":"The Younger Dryas caused the complete and permanent disappearance of all Natufian settlements in the Levant."},{"key":"C","text":"Amitai's isotope data prove that drought was the sole cause of every individual Natufian site abandonment."},{"key":"D","text":"Natufian communities near perennial springs experienced no effects whatsoever from the Younger Dryas climate shift."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that reduced rainfall coincided with settlement collapses, but Amitai explicitly notes both abandonments and new foundations occurred, and that some communities relocated to areas near perennial springs. The inference that reduced rainfall pressured some communities to relocate without causing uniform catastrophe aligns with this nuanced account. The choice describing complete and permanent disappearance contradicts the passage''s mention of new foundations and relocations during the same period. The choice claiming Amitai''s data prove drought as the sole cause overstates her findings; she cautions that her isotope record reflects regional moisture patterns, not site-specific conditions. The choice asserting that communities near springs experienced no effects at all goes beyond the evidence; the passage says they relocated to such areas as an adaptive response, not that those locations were wholly unaffected by climate change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QA5T5Y', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Paleontologist Jian-Ming Wu has argued that the rapid diversification of flowering plants during the mid-Cretaceous period was driven primarily by co-evolutionary relationships with pollinating insects. According to Wu, the development of specialized floral structures to attract specific pollinators created reproductive isolation between plant populations, accelerating the rate at which new species emerged.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ROIQHK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Clara Szilágyi has proposed that the synchronized flashing of Photinus carolinus fireflies—a phenomenon observed exclusively in a narrow elevation band of the southern Appalachian Mountains—relies on a biochemical feedback mechanism distinct from the neural oscillator model accepted for other ______ preliminary spectral data from her 2023 field season appear to corroborate this hypothesis, showing emission wavelength shifts that the oscillator model cannot account for.', $lyceon_json$[{"key":"A","text":"species; her"},{"key":"B","text":"species, in addition, her"},{"key":"C","text":"species, her"},{"key":"D","text":"species; nonetheless, her"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a semicolon to properly join two independent clauses: the first presents Szilágyi''s proposal about a distinct biochemical mechanism, and the second reports that her preliminary data corroborate the hypothesis. A semicolon without an additional conjunctive adverb is appropriate here because the second clause naturally extends and supports the first. The choice using a comma alone creates a comma splice between two independent clauses. The choice inserting ''in addition'' misrepresents the relationship—the data are not a separate, additional point but rather direct evidence for the hypothesis just described. The choice using ''nonetheless'' incorrectly implies a concessive relationship, as though the corroborating data stand in contrast to the proposal, when they actually support it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U9OKMX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Recent excavations at the Kaleshi Gorge site in central Anatolia have uncovered a sequence of ceramic vessels whose decorative motifs bear striking resemblance to those found at coastal Aegean settlements dating to 3200 BCE. The archaeologist Miruna Petrescu contends that these inland vessels, rather than being independent inventions, ______ through a network of overland trade routes that predates the maritime exchanges long considered the primary conduit for early Bronze Age cultural diffusion.', $lyceon_json$[{"key":"A","text":"was transmitted"},{"key":"B","text":"were transmitted"},{"key":"C","text":"have been transmitting"},{"key":"D","text":"has been transmitted"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is ''vessels,'' a plural noun separated from the verb by the parenthetical phrase ''rather than being independent inventions.'' The passive voice is required because the vessels were transmitted (carried or conveyed) through trade routes—they did not transmit themselves. The correct form is ''were transmitted,'' which provides both plural agreement and passive construction in the simple past tense appropriate for a historical event. The choice ''was transmitted'' uses a singular auxiliary that does not agree with the plural ''vessels.'' The choice ''have been transmitting'' uses the active voice with a present-perfect progressive tense, implying that the vessels are currently and continuously transmitting something, which is both logically incoherent and temporally inappropriate for events around 3200 BCE. The choice ''has been transmitted'' uses a singular auxiliary that fails to agree with ''vessels'' and employs the present perfect, which is inconsistent with the passage''s past-tense historical framing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WQWCYH', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student wants to present Mäkinen''s findings and explain why the observed pattern occurs. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X7GDVS', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the passage, which choice can most reasonably be inferred about the Arita potters'' modifications?', E'Historian Tomoko Arai has documented how Japanese porcelain manufacturers in the city of Arita adapted their designs during the seventeenth century to appeal to Dutch traders, who served as intermediaries for the European market. Arita potters began incorporating motifs — such as tulips, coats of arms, and pastoral landscapes — that had no precedent in Japanese visual tradition but resonated with European buyers. Arai notes that this adaptation was not merely superficial: the potters also modified glaze compositions to produce the brighter blues and reds favored in European tableware, even though these formulations required costlier imported cobalt and iron-oxide pigments.', $lyceon_json$[{"key":"A","text":"The potters prioritized market demand over adherence to established Japanese aesthetic conventions."},{"key":"B","text":"The potters concealed their design changes from Japanese consumers to avoid criticism."},{"key":"C","text":"Dutch traders dictated the exact specifications of every piece produced in Arita."},{"key":"D","text":"The use of imported pigments ultimately caused the Arita porcelain industry to collapse."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes potters adopting European motifs with no Japanese precedent and using costlier imported pigments to match European color preferences, indicating that they prioritized market demand over traditional Japanese aesthetics. The choice about concealing changes from Japanese consumers introduces a claim about secrecy that the passage does not address. The choice about Dutch traders dictating exact specifications overstates the relationship described; the passage says potters adapted their designs, not that traders controlled production in detail. The choice about industry collapse introduces an outcome not mentioned or implied anywhere in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XGW8BN', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the passage?', E'Marine biologists studying the kelp forests off the coast of Tasmania have documented a striking decline in canopy coverage over the past two decades. Between 2001 and 2021, approximately 95 percent of the giant kelp canopy in eastern Tasmania disappeared. The researchers attribute this loss primarily to the strengthening of the East Australian Current, which has carried warmer subtropical waters southward into regions that historically supported dense kelp growth. As water temperatures have risen, the cold-water kelp species Macrocystis pyrifera has been unable to sustain its characteristic rapid growth, leading to widespread die-offs.', $lyceon_json$[{"key":"A","text":"Warming ocean currents have caused a dramatic reduction in Tasmania's giant kelp forests."},{"key":"B","text":"Marine biologists have recently discovered a new species of kelp growing in Tasmanian waters."},{"key":"C","text":"The East Australian Current has shifted direction several times over the past century."},{"key":"D","text":"Macrocystis pyrifera is the only kelp species capable of growing in cold water."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the finding that warming waters from the strengthened East Australian Current have caused a 95 percent loss of giant kelp canopy in eastern Tasmania. The choice about warming ocean currents directly captures this central point. The choice about discovering a new species contradicts the passage, which discusses an existing species declining rather than a new one appearing. The choice about the current shifting direction multiple times goes beyond the passage, which states only that the current has strengthened. The choice claiming Macrocystis pyrifera is the only cold-water kelp species overstates a detail; the passage identifies it as a cold-water species but never claims it is the only one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YZOV8C', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2021 study, environmental economists analyzed the long-term fiscal impact of urban tree-planting initiatives in 37 mid-sized cities. They found that municipalities investing in canopy expansion saw measurable reductions in stormwater management costs within a decade. _______ the economists cautioned that these savings materialized only in cities that also maintained consistent pruning and replacement schedules; cities that planted trees but deferred maintenance saw no significant cost reduction and, in some cases, incurred higher infrastructure repair expenses from root damage.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Crucially, though,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Crucially, though," because the final sentence introduces an important qualification to the preceding finding: the cost savings depended on a condition (consistent maintenance) that limits the generality of the result. The word "though" signals contrast with the positive finding, and "crucially" conveys the importance of the caveat. "Furthermore" merely adds information without capturing the qualifying contrast. "Consequently" implies the caution is a result of the savings, which inverts the logical relationship. "For example" would introduce an illustration of the savings, but the sentence instead restricts their scope with a conditional caveat.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z2YA6V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geochemist Yael Nordström has documented unusually high concentrations of iridium in sedimentary layers at seventeen sites across the Canadian Shield. While iridium is typically associated with meteorite impacts, Nordström''s isotopic analysis suggests a volcanic ______ her findings challenge the prevailing assumption that such iridium anomalies invariably indicate extraterrestrial origin.', $lyceon_json$[{"key":"A","text":"origin; in contrast,"},{"key":"B","text":"origin, nevertheless,"},{"key":"C","text":"origin;"},{"key":"D","text":"origin, as a result,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses a semicolon to join two independent clauses. The first clause reports that Nordström''s analysis points to a volcanic origin for the iridium, and the second clause states that her findings challenge the assumption of extraterrestrial origin. These clauses are closely related and a semicolon appropriately links them without imposing an explicit logical connector. The choice using ''in contrast'' incorrectly signals opposition between the two clauses, but the second clause reinforces the first by stating its implication rather than presenting a contrasting idea. The choice using ''nevertheless'' with only a comma creates a comma splice — a conjunctive adverb cannot join independent clauses with just a comma. The choice using ''as a result'' mischaracterizes the relationship: the challenge to prevailing assumptions is not a separate consequence but a restatement of the finding''s significance.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZEIDR9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers studying the migration patterns of Arctic terns have documented flights spanning over 71,000 kilometers annually. These journeys, which take the birds from Arctic breeding grounds to Antarctic feeding areas and back, represent the longest known migration of any animal. The energy expenditure required for such distances would seem unsustainable. _______ the terns exploit prevailing wind currents along their route, effectively gliding for long stretches and reducing the metabolic cost of flight by an estimated 40 percent.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"As it turns out,"},{"key":"C","text":"In other words,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "As it turns out," because the preceding sentence raises an apparent problem (unsustainable energy expenditure), and the final sentence resolves it with a surprising explanation (wind current exploitation). This transition signals that the reality differs from what one might expect. "In addition" merely adds information and fails to capture the resolution of the tension set up in the prior sentence. "In other words" signals a restatement, but the final sentence introduces new information rather than rephrasing the preceding claim. "Meanwhile" implies simultaneous but separate events, which does not match the explanatory relationship between the sentences.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZIKIXO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In the early twentieth century, the textile mills of Lowell, Massachusetts, employed thousands of immigrant workers, many of whom had arrived from southern Europe with few resources. The wages ______ these workers during their first year of employment were often so meager that families pooled income from three or four household members simply to afford rent.', $lyceon_json$[{"key":"A","text":"paid to"},{"key":"B","text":"paying"},{"key":"C","text":"having paid"},{"key":"D","text":"that pays"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses the past participle ''paid to'' to form a participial phrase modifying ''wages.'' This construction—''The wages paid to these workers''—correctly indicates that the workers received the wages, with the past participle conveying passive meaning (the wages were paid to the workers). The choice using ''paying'' creates a present participial phrase implying the wages themselves are performing the action of paying, which is illogical since wages are received, not agents of payment. The choice using ''having paid'' suggests a completed prior action by the wages, which is nonsensical. The choice using ''that pays'' introduces a relative clause with a singular verb that does not agree with the plural subject ''wages,'' and also uses the present tense inappropriately for a passage set in the early twentieth century.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZKNP81', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, urban planners assumed that widening highways would reduce traffic congestion by increasing road capacity. However, transportation researchers have consistently observed a phenomenon known as "induced demand": when highways are expanded, the additional capacity attracts new drivers who previously used alternative routes or modes of transport. A 2019 study of thirty-seven metropolitan areas found that, within five years of a highway expansion, traffic volumes on the widened segments had returned to pre-expansion levels. These findings suggest that building more lanes is unlikely to provide lasting relief from congestion.', $lyceon_json$[{"key":"A","text":"It introduces a widespread belief, presents evidence that contradicts it, and draws a conclusion based on that evidence."},{"key":"B","text":"It compares two competing theories and argues that neither is fully supported by current data."},{"key":"C","text":"It describes a historical event, explains its causes, and evaluates its long-term consequences."},{"key":"D","text":"It summarizes a researcher's career achievements and highlights one particularly influential study."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing the structure as introducing a widespread belief, presenting contradicting evidence, and drawing a conclusion. The passage first states the planners'' assumption (widening highways reduces congestion), then introduces the contradicting phenomenon of induced demand with supporting data, and concludes that expansion is unlikely to solve congestion. The choice about two competing theories is incorrect because the passage presents only one theory and then refutes it rather than comparing two. The choice about a historical event is incorrect because the passage discusses an ongoing policy debate and research finding, not a single historical event with causes and consequences. The choice about a researcher''s career is incorrect because the passage does not focus on any individual researcher''s achievements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
